```python
def proxy_bypass_environment(host, proxies=None):
    """Test if proxies should not be used for a particular host."""
    if proxies is None:
        proxies = getproxies_environment()
    try:
        no_proxy = proxies['no']
    except KeyError:
        return 0
    if no_proxy == '*':
        return 1
    # strip port if present
    host = host.split(':')[0]
    # multiple entries in no_proxy separated by commas
    for name in no_proxy.split(','):
        name = name.strip()
        if name:
            # leading dots are matched only at the end of the hostname
            if name.startswith('.'):
                name = name.lstrip('.')
            # now, if the hostname ends with this no_proxy entry,
            # then the request should bypass the proxy
            if host == name or host.endswith('.' + name):
                return 1
    return 0
```

